Object.assign(catalog,{"modelConvergence":"Model convergence","whyConvergence":"Understand convergence","historicalConfidence":"Local historical confidence","historicalConfidenceMeta":"{count} calibrated models · {families} families","historicalConfidenceInsufficient":"Not enough comparable history across multiple families.","independentFamilies":"{count} model families","familiesShort":"families","centralMethodLocal":"Central forecast · locally weighted median","centralMethodFamily":"Central forecast · family-balanced median","weightedMedianCentral":"Weighted median balanced by model family","rainCentralHint":"P(rain) {probability}% · {amount} mm if wet","rainCentralNoProbability":"Conditional amount if wet","rainExpectedAmount":"Probability-weighted amount: {amount} mm","rainProbabilityShort":"P(rain) {probability}%","mixedRainProbability":"probabilities + deterministic models","centralForecastLine":"Central forecast ({unit})","agreement":"Convergence","globalAgreement":"Model convergence","whyAgreement":"Understand convergence","confidenceBand":"Hourly convergence band","chart_confidence_band_desc":"The band shows the raw model range; its color shows convergence after model-family balancing.","agreementNotAccuracy":"Convergence is not an accuracy probability.","agreementNotAccuracyBody":"It measures current proximity between model families. Local historical confidence is computed separately from past errors.","methodTemp":"Temperature: weighted median for the central forecast; convergence is based on dispersion across model families.","methodWind":"Wind: weighted median for the central forecast; convergence is based on dispersion across model families.","methodRain":"Rain: P(rain) is estimated separately from amount conditional on rain; convergence combines wet/dry agreement and wet-amount dispersion.","localWeightedConsensus":"Local weighting of the central forecast","localWeightedConsensusIntro":"Optional: slightly adjusts the central forecast and convergence using local historical reliability, without giving sibling models independent extra votes.","localWeightedConsensusNote":"Weights remain bounded (0.75×–1.25×). Original model outputs stay unchanged and visible; only the central synthesis and convergence are weighted.","aboutStepReadBody":"Weighted medians, rain probabilities, ranges, scenarios and convergence summarize models without hiding their original values.","aboutAgreementTitle":"Convergence and confidence","aboutAgreementBody":"Convergence measures current dispersion across model families. Local historical confidence separately measures past performance when comparable history is available.","aboutAgreementCallout":"High convergence does not guarantee accuracy: several model families can converge and still be wrong. Historical confidence provides a second independent signal."});

